import React, { useState } from 'react';
import { Edit, Trash2, MoreVertical } from 'lucide-react';

const UsersTable = ({ onEdit = null, onDelete = null }) => {
  const [users, setUsers] = useState([
    { id: 1, name: 'Alex Johnson', email: 'alex@example.com', role: 'Admin', status: 'active', joinDate: '2023-12-01' },
    { id: 2, name: 'Maria Garcia', email: 'maria@example.com', role: 'Editor', status: 'active', joinDate: '2023-11-15' },
    { id: 3, name: 'David Chen', email: 'david@example.com', role: 'User', status: 'inactive', joinDate: '2023-10-20' },
    { id: 4, name: 'Sarah Wilson', email: 'sarah@example.com', role: 'User', status: 'active', joinDate: '2023-09-05' },
    { id: 5, name: 'Michael Brown', email: 'michael@example.com', role: 'Moderator', status: 'active', joinDate: '2023-08-12' },
  ]);

  const [mobileMenuOpen, setMobileMenuOpen] = useState(null);

  const handleEdit = (user) => {
    if (onEdit) {
      onEdit(user);
    }
  };

  const handleDelete = (userId) => {
    if (onDelete) {
      onDelete(userId);
    } else {
      setUsers(users.filter(user => user.id !== userId));
    }
  };

  return (
    <>
      {/* Vue desktop */}
      <div className="hidden md:block bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl shadow-lg border border-white/30 dark:border-neutral-800/50 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-neutral-200 dark:border-neutral-700">
                <th className="pb-3 px-6 text-left text-sm font-medium text-neutral-600 dark:text-neutral-400">Utilisateur</th>
                <th className="pb-3 px-6 text-left text-sm font-medium text-neutral-600 dark:text-neutral-400">Email</th>
                <th className="pb-3 px-6 text-left text-sm font-medium text-neutral-600 dark:text-neutral-400">Rôle</th>
                <th className="pb-3 px-6 text-left text-sm font-medium text-neutral-600 dark:text-neutral-400">Statut</th>
                <th className="pb-3 px-6 text-left text-sm font-medium text-neutral-600 dark:text-neutral-400">Date d'inscription</th>
                <th className="pb-3 px-6 text-left text-sm font-medium text-neutral-600 dark:text-neutral-400">Actions</th>
              </tr>
            </thead>
            <tbody>
              {users.map((user) => (
                <tr key={user.id} className="border-b border-neutral-100 dark:border-neutral-800/50 last:border-0 hover:bg-neutral-50 dark:hover:bg-neutral-800/30 transition-colors">
                  <td className="py-4 px-6">
                    <div className="flex items-center space-x-3">
                      <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center">
                        <span className="text-white font-medium">{user.name.charAt(0)}</span>
                      </div>
                      <div>
                        <p className="font-medium text-neutral-900 dark:text-white">{user.name}</p>
                      </div>
                    </div>
                  </td>
                  <td className="py-4 px-6 text-neutral-600 dark:text-neutral-400">{user.email}</td>
                  <td className="py-4 px-6">
                    <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                      user.role === 'Admin' ? 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400' :
                      user.role === 'Editor' ? 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400' :
                      user.role === 'Moderator' ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400' :
                      'bg-neutral-100 text-neutral-800 dark:bg-neutral-800 dark:text-neutral-400'
                    }`}>
                      {user.role}
                    </span>
                  </td>
                  <td className="py-4 px-6">
                    <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                      user.status === 'active' ? 'bg-accent-100 text-accent-800 dark:bg-accent-900/30 dark:text-accent-400' :
                      'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400'
                    }`}>
                      {user.status === 'active' ? 'Actif' : 'Inactif'}
                    </span>
                  </td>
                  <td className="py-4 px-6 text-neutral-600 dark:text-neutral-400">{user.joinDate}</td>
                  <td className="py-4 px-6">
                    <div className="flex items-center space-x-2">
                      <button 
                        onClick={() => handleEdit(user)}
                        className="p-2 text-neutral-500 hover:text-primary-600 dark:hover:text-primary-400 transition-colors"
                      >
                        <Edit className="h-4 w-4" />
                      </button>
                      <button 
                        onClick={() => handleDelete(user.id)}
                        className="p-2 text-neutral-500 hover:text-red-600 dark:hover:text-red-400 transition-colors"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Vue mobile */}
      <div className="md:hidden space-y-4">
        {users.map((user) => (
          <div key={user.id} className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-xl p-4 shadow-lg border border-white/30 dark:border-neutral-800/50">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center space-x-3">
                <div className="h-12 w-12 rounded-full bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center">
                  <span className="text-white font-medium text-lg">{user.name.charAt(0)}</span>
                </div>
                <div>
                  <p className="font-medium text-neutral-900 dark:text-white">{user.name}</p>
                  <p className="text-sm text-neutral-600 dark:text-neutral-400 truncate max-w-[150px]">
                    {user.email}
                  </p>
                </div>
              </div>
              <button 
                onClick={() => setMobileMenuOpen(mobileMenuOpen === user.id ? null : user.id)}
                className="p-2 text-neutral-500 hover:text-primary-600 dark:hover:text-primary-400"
              >
                <MoreVertical className="h-5 w-5" />
              </button>
            </div>

            <div className="grid grid-cols-2 gap-3 mb-3">
              <div>
                <span className="text-xs text-neutral-500 dark:text-neutral-400">Rôle</span>
                <span className={`block px-3 py-1 rounded-full text-xs font-medium mt-1 ${
                  user.role === 'Admin' ? 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400' :
                  user.role === 'Editor' ? 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400' :
                  user.role === 'Moderator' ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400' :
                  'bg-neutral-100 text-neutral-800 dark:bg-neutral-800 dark:text-neutral-400'
                }`}>
                  {user.role}
                </span>
              </div>
              <div>
                <span className="text-xs text-neutral-500 dark:text-neutral-400">Statut</span>
                <span className={`block px-3 py-1 rounded-full text-xs font-medium mt-1 ${
                  user.status === 'active' ? 'bg-accent-100 text-accent-800 dark:bg-accent-900/30 dark:text-accent-400' :
                  'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400'
                }`}>
                  {user.status === 'active' ? 'Actif' : 'Inactif'}
                </span>
              </div>
            </div>

            <div className="text-sm text-neutral-600 dark:text-neutral-400">
              <span className="font-medium">Inscrit le:</span> {user.joinDate}
            </div>

            {/* Menu mobile */}
            {mobileMenuOpen === user.id && (
              <div className="mt-3 pt-3 border-t border-neutral-200 dark:border-neutral-700">
                <div className="flex space-x-2">
                  <button 
                    onClick={() => {
                      handleEdit(user);
                      setMobileMenuOpen(null);
                    }}
                    className="flex-1 flex items-center justify-center space-x-2 py-2 rounded-lg bg-primary-50 dark:bg-primary-900/20 text-primary-600 dark:text-primary-400 hover:bg-primary-100 dark:hover:bg-primary-900/30 transition-colors"
                  >
                    <Edit className="h-4 w-4" />
                    <span className="text-sm">Modifier</span>
                  </button>
                  <button 
                    onClick={() => {
                      handleDelete(user.id);
                      setMobileMenuOpen(null);
                    }}
                    className="flex-1 flex items-center justify-center space-x-2 py-2 rounded-lg bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-900/30 transition-colors"
                  >
                    <Trash2 className="h-4 w-4" />
                    <span className="text-sm">Supprimer</span>
                  </button>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </>
  );
};

export default UsersTable;
